import { getOAuthConsumer, updateOAuthConsumer } from '../../clever-client/oauth-consumers.js';
import { defineCommand } from '../../lib/define-command.js';
import { Logger } from '../../logger.js';
import { getOwnerIdFromOrgIdOrName } from '../../models/ids-resolver.js';
import { sendToApi } from '../../models/send-to-api.js';
import { humanJsonOutputFormatOption, orgaIdOrNameOption } from '../global.options.js';
import { consumerKeyArg } from './oauth-consumers.args.js';
import {
  consumerBaseUrlOption,
  consumerDescriptionOption,
  consumerNameOption,
  consumerPictureOption,
  consumerRightsOption,
  consumerUrlOption,
  toConsumerBody,
} from './oauth-consumers.options.js';

export const oauthConsumersUpdateCommand = defineCommand({
  description: 'Update an OAuth consumer',
  since: null,
  options: {
    org: orgaIdOrNameOption,
    name: consumerNameOption,
    description: consumerDescriptionOption,
    url: consumerUrlOption,
    baseUrl: consumerBaseUrlOption,
    picture: consumerPictureOption,
    rights: consumerRightsOption,
    format: humanJsonOutputFormatOption,
  },
  args: [consumerKeyArg],
  async handler(options, key) {
    const { org, format, ...fields } = options;
    const changes = toConsumerBody(fields);
    if (Object.keys(changes).length === 0) {
      throw new Error('Nothing to update, pass at least one of --name, --description, --url, --base-url, --picture, --rights');
    }

    const id = await getOwnerIdFromOrgIdOrName(org);
    // The API replaces the whole consumer, so we start from the current one
    const current = await getOAuthConsumer({ id, key }).then(sendToApi);
    const { name, description, url, baseUrl, picture, rights } = current;
    const body = { name, description, url, baseUrl, picture, rights, ...changes };
    const consumer = await updateOAuthConsumer({ id, key, body }).then(sendToApi);

    if (format === 'json') {
      Logger.printJson(consumer);
    } else {
      Logger.printSuccess(`OAuth consumer ${key} updated successfully`);
    }
  },
});
EOF
